script:
function flexi_document_title(row) {
    const titles = {
        "HP-AGREEMENT": "Hire Purchase Agreement",
        "SCHEDULE-1": "Contents of Credit Contract",
        "FORM-1": "Information Statement",
        "FORM-2": "Form 2",
        "FINANCIAL-OBLIGATIONS": "Summary of Financial Obligations"
    };
    return titles[row.document_code] || row.document_code || "Customer Document";
}

function flexi_can_open_document(frm, row) {
    const rows = frm.doc.custom_customer_documents || [];
    const index = rows.findIndex(item => item.name === row.name);
    if (index <= 0) return true;
    const previous = rows[index - 1];
    if (previous.status !== "Completed") {
        frappe.msgprint(__("Please complete {0} before continuing.", [flexi_document_title(previous)]));
        return false;
    }
    return true;
}

function flexi_signature_fields(row, frm) {
    const fields = [
        { fieldname: "document_reader", fieldtype: "HTML" }
    ];
    if (row.document_code === "HP-AGREEMENT") {
        fields.push(
            { fieldtype: "Section Break", label: __("Agreement Reference") },
            {
                fieldname: "hp_reference_no",
                fieldtype: "Data",
                label: __("HP Reference / Quotation No"),
                default: frm.doc.custom_flexi_quotation_number || "",
                description: __("Enter the reference that must appear on the signed Hire Purchase Agreement.")
            }
        );
    }
    fields.push(
        { fieldtype: "Section Break", label: __("Customer Acknowledgement") },
        {
            fieldname: "acknowledged",
            fieldtype: "Check",
            label: __("I confirm that I have read, understood and agree to this document."),
            read_only: 1
        },
        { fieldtype: "Section Break", label: __("Customer Signature") },
        { fieldname: "customer_signature", fieldtype: "Signature", label: __("Draw Signature") },
        { fieldname: "customer_signature_file", fieldtype: "Attach Image", label: __("Or Attach Signature Image") }
    );
    if (row.document_code === "FORM-1") {
        fields.push(
            { fieldtype: "Section Break", label: __("Witness Details") },
            { fieldname: "witness_name", fieldtype: "Data", label: __("Witness Name"), default: frm.doc.custom_witness_name || "" },
            { fieldname: "witness_address", fieldtype: "Small Text", label: __("Witness Address"), default: frm.doc.custom_witness_address || "" },
            { fieldname: "witness_date", fieldtype: "Date", label: __("Witness Date"), default: frm.doc.custom_witness_date || frappe.datetime.get_today() },
            { fieldname: "witness_signature", fieldtype: "Signature", label: __("Witness Signature") }
        );
    }
    return fields;
}

function flexi_open_customer_signing(frm, row) {
    const title = flexi_document_title(row);
    const dialog = new frappe.ui.Dialog({
        title: __(title),
        size: "extra-large",
        fields: flexi_signature_fields(row, frm),
        primary_action_label: __("Agree & Sign"),
        primary_action(values) {
            if (!dialog.flexi_document_loaded) {
                frappe.msgprint(__("The document is still loading."));
                return;
            }
            if (!values.acknowledged) {
                frappe.msgprint(__("Please scroll through the complete document before acknowledging it."));
                return;
            }
            if (!values.customer_signature && !values.customer_signature_file) {
                frappe.msgprint(__("Please draw your signature or attach a signature image."));
                return;
            }
            if (row.document_code === "FORM-1" && (!values.witness_name || !values.witness_address || !values.witness_signature)) {
                frappe.msgprint(__("Witness name, address and signature are required for the Information Statement."));
                return;
            }
            frappe.call({
                method: "flexi_document_customer_sign",
                args: {
                    docname: frm.doc.name,
                    rowname: row.name,
                    acknowledged: 1,
                    signature: values.customer_signature || "",
                    signature_file: values.customer_signature_file || "",
                    witness_name: values.witness_name || "",
                    witness_address: values.witness_address || "",
                    witness_date: values.witness_date || "",
                    witness_signature: values.witness_signature || "",
                    hp_reference_no: values.hp_reference_no === undefined ? null : values.hp_reference_no
                },
                freeze: true,
                freeze_message: __("Applying customer signature..."),
                callback(response) {
                    const result = response.message || {};
                    if (result.html && dialog.flexi_iframe) dialog.flexi_iframe.srcdoc = result.html;
                    frappe.show_alert({
                        message: result.status === "Completed" ? __("Signed copy attached to the Loan Application") : __("Customer signature applied"),
                        indicator: "green"
                    }, 6);
                    dialog.set_primary_action(__("Close"), () => {
                        dialog.hide();
                        frm.reload_doc();
                    });
                }
            });
        }
    });
    dialog.flexi_document_loaded = false;
    dialog.show();
    const wrapper = dialog.fields_dict.document_reader.$wrapper;
    wrapper.html(`<div style="padding:40px;text-align:center;color:#6c7680;">Preparing ${frappe.utils.escape_html(title)}...</div>`);

    frappe.call({
        method: "flexi_document_preview",
        args: { docname: frm.doc.name, rowname: row.name },
        callback(response) {
            const result = response.message || {};
            if (!result.html) {
                wrapper.html('<div class="alert alert-danger">No document content was returned.</div>');
                return;
            }
            wrapper.empty();
            const iframe = document.createElement("iframe");
            iframe.style.cssText = "width:100%;height:65vh;border:1px solid #d1d8dd;background:#fff;display:block";
            iframe.srcdoc = result.html;
            iframe.onload = () => {
                dialog.flexi_document_loaded = true;
                const acknowledgement = dialog.fields_dict.acknowledged;
                const enableAcknowledgement = () => {
                    acknowledgement.df.read_only = 0;
                    acknowledgement.refresh();
                };
                try {
                    const documentElement = iframe.contentDocument.documentElement;
                    const body = iframe.contentDocument.body;
                    const scroller = documentElement.scrollHeight >= body.scrollHeight ? documentElement : body;
                    if (scroller.scrollHeight <= iframe.clientHeight + 10) {
                        enableAcknowledgement();
                    } else {
                        iframe.contentWindow.addEventListener("scroll", () => {
                            const root = iframe.contentDocument.documentElement;
                            const page = iframe.contentDocument.body;
                            const top = Math.max(root.scrollTop, page.scrollTop);
                            const height = Math.max(root.scrollHeight, page.scrollHeight);
                            if (top + iframe.clientHeight >= height - 30) enableAcknowledgement();
                        });
                    }
                } catch (error) {
                    enableAcknowledgement();
                }
            };
            dialog.flexi_iframe = iframe;
            wrapper.append(iframe);
            wrapper.append('<div style="font-size:12px;color:#6c7680;padding:8px 0 10px;">Scroll to the end of the document to unlock acknowledgement and signing.</div>');
        }
    });
}

function flexi_open_director_signing(frm, row) {
    const title = flexi_document_title(row);
    const dialog = new frappe.ui.Dialog({
        title: __("{0} - Company Sign", [title]),
        size: "extra-large",
        fields: [
            { fieldname: "document_reader", fieldtype: "HTML" },
            { fieldtype: "Section Break", label: __("Director / Manager") },
            { fieldname: "director_name", fieldtype: "Data", label: __("Director / Manager Name"), reqd: 1 },
            { fieldname: "director_signature", fieldtype: "Signature", label: __("Draw Director / Manager Signature") },
            { fieldname: "director_signature_file", fieldtype: "Attach Image", label: __("Or Attach Signature Image") }
        ],
        primary_action_label: __("Complete & Attach Signed Copy"),
        primary_action(values) {
            if (!values.director_name || (!values.director_signature && !values.director_signature_file)) {
                frappe.msgprint(__("Director / Manager name and signature are required."));
                return;
            }
            frappe.call({
                method: "flexi_document_director_sign",
                args: {
                    docname: frm.doc.name,
                    rowname: row.name,
                    director_name: values.director_name,
                    director_signature: values.director_signature || "",
                    director_signature_file: values.director_signature_file || ""
                },
                freeze: true,
                freeze_message: __("Finalizing signed document..."),
                callback(response) {
                    const result = response.message || {};
                    if (result.html && dialog.flexi_iframe) dialog.flexi_iframe.srcdoc = result.html;
                    frappe.show_alert({ message: __("Final signed copy attached to the Loan Application"), indicator: "green" }, 6);
                    dialog.set_primary_action(__("Close"), () => {
                        dialog.hide();
                        frm.reload_doc();
                    });
                }
            });
        }
    });
    dialog.show();
    const wrapper = dialog.fields_dict.document_reader.$wrapper;
    wrapper.html('<div style="padding:40px;text-align:center;color:#6c7680;">Preparing customer-signed document...</div>');
    frappe.call({
        method: "flexi_document_preview",
        args: { docname: frm.doc.name, rowname: row.name },
        callback(response) {
            const result = response.message || {};
            if (!result.html) {
                wrapper.html('<div class="alert alert-danger">Could not load the document.</div>');
                return;
            }
            wrapper.empty();
            const iframe = document.createElement("iframe");
            iframe.style.cssText = "width:100%;height:65vh;border:1px solid #d1d8dd;background:#fff";
            iframe.srcdoc = result.html;
            dialog.flexi_iframe = iframe;
            wrapper.append(iframe);
        }
    });
}

function flexi_open_customer_document(frm, row) {
    if (!flexi_can_open_document(frm, row)) return;
    if (row.status === "Completed") {
        if (row.final_signed_file) window.open(row.final_signed_file, "_blank");
        else frappe.msgprint(__("The final signed copy is not available."));
        return;
    }
    if (row.status === "Customer Signed" || row.status === "Director Signed") {
        flexi_open_director_signing(frm, row);
        return;
    }
    flexi_open_customer_signing(frm, row);
}

function flexi_add_document_buttons(frm) {
    const rows = frm.doc.custom_customer_documents || [];
    rows.forEach(row => {
        const status = row.status || "Pending";
        const icon = status === "Completed" ? "✓" : "•";
        frm.add_custom_button(
            __(`${icon} ${flexi_document_title(row)} — ${status}`),
            () => flexi_open_customer_document(frm, row),
            __("Customer Documents")
        );
    });
}

frappe.ui.form.on("Loan Application", {
    refresh(frm) {
        if (frm.is_new()) return;
        flexi_add_document_buttons(frm);
        if (!frm.__flexi_documents_synced) {
            frm.__flexi_documents_synced = true;
            frappe.call({
                method: "flexi_document_sync",
                args: { docname: frm.doc.name },
                callback(response) {
                    if ((response.message || {}).added) frm.reload_doc();
                }
            });
        }
    }
});
/* This block is appended to Flexi Customer Document Signing through fixtures. */

function flexi_customer_documents_complete(frm) {
	return (frm.doc.custom_customer_documents || [])
		.filter((row) => row.document_code !== "REQ" && row.document_template !== "LDT-00007")
		.every((row) => ["Customer Signed", "Director Signed", "Completed"].includes(row.status));
}

function flexi_can_open_document(frm, row) {
	return true;
}

function flexi_open_customer_document(frm, row) {
	if (row.document_code === "REQ" || row.document_template === "LDT-00007") return;
	if (row.status === "Completed" || row.status === "Director Signed") {
		if (row.final_signed_file) window.open(row.final_signed_file, "_blank");
		else frappe.msgprint(__("The final signed copy is not available."));
		return;
	}
	if (row.status === "Customer Signed") {
		if (!flexi_customer_documents_complete(frm)) {
			frappe.msgprint(__("Complete every customer document before the Director / Manager signs."));
			return;
		}
		flexi_open_director_signing(frm, row);
		return;
	}
	flexi_open_customer_signing(frm, row);
}

function flexi_add_document_buttons(frm) {
	(frm.doc.custom_customer_documents || [])
		.filter((row) => row.document_code !== "REQ" && row.document_template !== "LDT-00007")
		.forEach((row) => {
			const status = row.status || "Pending";
			const icon = status === "Completed" ? "✓" : "•";
			frm.add_custom_button(
				__(icon + " " + flexi_document_title(row) + " — " + status),
				() => flexi_open_customer_document(frm, row),
				__("Customer Documents")
			);
		});
}

function import_statement_dialog(frm, analysis) {
	const columns = [""].concat(analysis.columns || []).join("\n");
	const mapping = analysis.mapping || {};
	const dialog = new frappe.ui.Dialog({
		title: "Review statement mapping",
		fields: [
			{ fieldname: "summary", fieldtype: "HTML", options: `<p>Detected ${analysis.file_name}. ${analysis.sheets.length > 1 ? `${analysis.sheets.length} sheets will be imported.` : ""}</p>` },
			{ fieldname: "date", label: "Transaction / value date column", fieldtype: "Select", options: columns, default: mapping.date, reqd: 1 },
			{ fieldname: "description", label: "Description column", fieldtype: "Select", options: columns, default: mapping.description, reqd: 1 },
			{ fieldname: "credit", label: "Credit / money received column", fieldtype: "Select", options: columns, default: mapping.credit },
			{ fieldname: "amount", label: "Single amount column (if no credit column)", fieldtype: "Select", options: columns, default: mapping.amount },
		],
		primary_action_label: "Import credits",
		primary_action(values) {
			if (!values.credit && !values.amount) {
				frappe.msgprint("Choose a credit column or a single amount column.");
				return;
			}
			dialog.hide();
			frappe.call({
				method: "comfort_homes.api.loan_reconciliation",
				args: { name: frm.doc.name, action: "import_statement", mapping: values },
				freeze: true,
				freeze_message: "Importing statement credits…",
				callback(r) {
					if (!r.exc) {
						frappe.show_alert({ message: `${r.message.imported} credits imported. ${r.message.ready} ready; ${r.message.review} need review.`, indicator: "green" });
						frm.reload_doc();
					}
				}
			});
		}
	});
	dialog.show();
}

frappe.ui.form.on("Loan Bank Reconciliation", {
	refresh(frm) {
		frm.set_query("loan", "transactions", (_doc, cdt, cdn) => {
			const row = locals[cdt][cdn];
			if (!row.customer) {
				// An unknown payer must be matched to a customer first.
				return { filters: { name: "__no_customer_matched__" } };
			}
			return {
				filters: {
					applicant: row.customer,
					applicant_type: "Customer",
					status: "Disbursed",
					docstatus: 1,
				},
			};
		});

		if (frm.is_new()) return;
		frm.add_custom_button("Import bank statement", () => {
			if (!frm.doc.statement_file) {
				frappe.msgprint("Attach a CSV or Excel bank statement, then save this reconciliation first.");
				return;
			}
			frappe.call({
				method: "comfort_homes.api.analyse_statement",
				args: { name: frm.doc.name },
				freeze: true,
				freeze_message: "Analysing statement format…",
				callback(r) {
					if (!r.exc) import_statement_dialog(frm, r.message);
				}
			});
		}, "Actions");

		if (frm.doc.transactions && frm.doc.transactions.length) {
			frm.add_custom_button("Create Loan Repayments", () => {
				const row_names = (frm.get_selected().transactions || []).map((row) => row.name);
				const scope = row_names.length
					? `Create repayments for the ${row_names.length} ticked row(s) that are ready?`
					: "No rows are ticked. Create repayments for every ready row?";
				frappe.confirm(
					scope,
					() => frappe.call({
						method: "comfort_homes.api.loan_reconciliation",
						args: { name: frm.doc.name, action: "create_repayments", row_names },
						freeze: true,
						freeze_message: "Creating loan repayments…",
						callback(r) {
							if (!r.exc) {
								const errors = r.message.errors || [];
								frappe.msgprint({ title: "Loan reconciliation", message: `${r.message.created} repayment(s) created. ${r.message.skipped} row(s) skipped.` + (errors.length ? `<br><br>${errors.join("<br>")}` : ""), indicator: errors.length ? "orange" : "green" });
								frm.reload_doc();
							}
						}
					})
				);
			}, "Actions");
		}
	}
});

frappe.ui.form.on("Loan Bank Reconciliation Item", {
	loan(frm, cdt, cdn) {
		const row = locals[cdt][cdn];
		if (row.loan && !row.loan_repayment) {
			frappe.model.set_value(cdt, cdn, "selected", 1);
			frappe.model.set_value(cdt, cdn, "status", "Ready");
		}
	}
});
